  Serial.begin(115200);
  pinMode(D0, OUTPUT);
  WiFi.begin(ssid, sifre);
  while (WiFi.status() != WL_CONNECTED) { delay(500); Serial.print("."); }
  Serial.println(WiFi.localIP());
  server.on("/", anaSayfa);
  server.on("/led", ledYolu);
  server.begin();
}

